<?php
namespace Modules\Finance\Http\Controllers;
use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Illuminate\Validation\Rule;use Modules\Core\Services\AuditService;use Modules\Core\Support\CurrentCompany;use Modules\Finance\Models\BankAccount;use Modules\Finance\Models\BankStatementImport;use Modules\Finance\Models\BankStatementLine;use Modules\Finance\Services\BankReconciliationService;use RuntimeException;
class BankReconciliationController extends Controller{public function __construct(private BankReconciliationService$service,private AuditService$audit){}public function accounts():JsonResponse{return response()->json(['data'=>BankAccount::where('company_id',CurrentCompany::id())->orderBy('code')->get()]);}public function createAccount(Request$request):JsonResponse{$company=CurrentCompany::id();$data=$request->validate(['code'=>'required|string|max:32','name'=>'required|string|max:255','bank_name'=>'required|string|max:255','currency_id'=>['nullable','integer',Rule::exists('currencies','id')->where('company_id',$company)],'coa_id'=>['required','integer',Rule::exists('chart_of_accounts','id')->where('company_id',$company)]]);$account=BankAccount::create($data+['company_id'=>$company,'created_by'=>$request->user()->id]);$this->audit->record('create',$account,after:$account->toArray(),request:$request);return response()->json($account,201);}public function import(Request$request,BankAccount$bankAccount):JsonResponse{$data=$request->validate(['statement_no'=>'required|string|max:64','period_start'=>'required|date_format:Y-m-d','period_end'=>'required|date_format:Y-m-d','opening_balance'=>'required|numeric','closing_balance'=>'required|numeric','rows'=>'required|array|min:1|max:5000','rows.*.transaction_date'=>'required|date_format:Y-m-d','rows.*.value_date'=>'nullable|date_format:Y-m-d','rows.*.direction'=>['required',Rule::in(['DEBIT','CREDIT'])],'rows.*.amount'=>'required|numeric|gt:0','rows.*.reference_no'=>'nullable|string|max:128','rows.*.description'=>'nullable|string|max:2000']);$rows=$data['rows'];unset($data['rows']);return$this->domain(fn()=>response()->json($this->service->import($bankAccount,$data,$rows,$request->user()),201));}public function show(BankStatementImport$bankStatementImport):JsonResponse{return response()->json($bankStatementImport->load('lines.matches'));}public function match(Request$request,BankStatementLine$bankStatementLine):JsonResponse{$data=$request->validate(['source_type'=>['required',Rule::in(['AR_PAYMENT','AP_PAYMENT'])],'source_id'=>'required|integer|min:1','amount'=>'required|numeric|gt:0']);return$this->domain(fn()=>response()->json($this->service->match($bankStatementLine,$data['source_type'],$data['source_id'],(float)$data['amount'],$request->user())));}public function ignore(Request$request,BankStatementLine$bankStatementLine):JsonResponse{$data=$request->validate(['reason'=>'required|string|max:500']);return$this->domain(fn()=>response()->json($this->service->ignore($bankStatementLine,$data['reason'],$request->user())));}public function fee(Request$request,BankStatementLine$bankStatementLine):JsonResponse{$data=$request->validate(['amount'=>'required|numeric|gt:0']);return$this->domain(fn()=>response()->json($this->service->bankFee($bankStatementLine,(float)$data['amount'],$request->user())));}public function reconcile(Request$request,BankStatementImport$bankStatementImport):JsonResponse{return$this->domain(fn()=>response()->json($this->service->reconcile($bankStatementImport,$request->user())));}private function domain(callable$callback):JsonResponse{try{return$callback();}catch(RuntimeException$e){return response()->json(['message'=>$e->getMessage()],422);}}}
